"""Byte snapshots generated by executing the real 85888d5 engine offline.

The expected hashes were captured before implementation from git archive.
Running these regressions needs neither git history nor files outside the repo.
P1 reviewer system rules intentionally change under T5; user payloads do not.
"""
import asyncio
import hashlib
import inspect
import json

import pytest

from novel.bible import build_setup
from novel.deliberation import deliberate
from novel.fake_llm import FakeLLM
from novel.schemas import parse_json
from novel.writing import write_chapter


BASELINE = {
    "solo": {"steps": 12, "bible_version": 5,
             "keys": "8e6259f727bc9c5fef113ebbd9e27dabdc29a571822deeb6815bea8c2347f965",
             "payloads": "3c9ca72b2901741829c4a97e7973f6932507a1591f8471c52840c8cf9dbdb0e0",
             "output": "a97664f299b2833e454ff9b16f75a29ef1f763e9b887559d05115fd1ad78fa8d"},
    "critique": {"steps": 24, "bible_version": 5,
                 "keys": "da5a4b40c3ced43b8e7f8e083b39b18c030c0314ae2b868692270c0b95f699f0",
                 "payloads": "47e40b678068fc1e363fca15c03f6382da65b5edc8c622b6ed40c6ccc4b44170",
                 "output": "85c6c8d024b4e105a27074078abafd0af4838796b07e881e4f7261b2469fa2b7"},
    "merge": {"steps": 30, "bible_version": 5,
              "keys": "10f00898e908bb2a9a6bf4c35df3c8aae93d0b85512beb2c4940c63e424797e2",
              "payloads": "d9884049454ba56b6cbfb3bd03a8e4cff80145f11e262e680225fff4b5f8fddb",
              "output": "e83db0b844ad064e356e8de07ac2fe04993e707301034dec267811003f8f5a59"},
}


class RecordingRouter:
    def __init__(self):
        self.fake = FakeLLM()

    async def call(self, **request):
        validator = request.pop("validator", None)
        raw, _usage = await self.fake(request)
        result = parse_json(raw) if request.get("output", "json") == "json" else raw
        return validator(result) if validator else result


def engine_snapshot(mode, structure=None):
    async def scenario():
        roles = ["editor", "writer", "reviewer", "archivist"]
        if mode != "solo":
            roles += ["pacing_advisor", "reader_rep", "twist_designer"]
        config = {"seed_idea": "保全旧案原件", "experiment": "P1", "panel_mode": mode,
                  "critique_rounds": 1, "enable_arc_summaries": True,
                  "enable_context_compression": True,
                  "target": {"min_chapters": 3, "max_chapters": 3, "chapter_words": 300},
                  "adaptation": {"max_main_characters": 6, "max_scenes_per_chapter": 3},
                  "agents": {role: f"fake:{role}" for role in roles}}
        if structure is not None:
            config["structure"] = structure
        router = RecordingRouter()
        compass, bible = build_setup(router.fake.default_response({"task": "setup"}), config)
        # P1 setup approval already created the user-edit version.
        bible["version"] = 2
        history, products, meetings = [], [], []
        previous = ""
        arm = "solo" if mode == "solo" else "panel"
        for chapter in range(1, 4):
            meeting = await deliberate(router, config, compass, bible, chapter=chapter, arm=arm,
                                      participants=[role for role in roles if role not in
                                                    ("writer", "reviewer", "archivist")],
                                      history=history)
            product = await write_chapter(router, config, compass, bible, meeting,
                                          chapter=chapter, arm=arm, previous_text=previous)
            previous, bible = product["body"], product["bible"]
            history.append({"chapter": chapter, "ending_status": meeting["decision"]["ending_status"]})
            products.append(product)
            meetings.append(meeting)
        calls = router.fake.calls
        payloads = [[call["step_key"], [message["content"] for message in call["messages"]
                                       if message["role"] == "user"]] for call in calls]
        keys = [call["step_key"] for call in calls]

        def digest(value):
            encoded = json.dumps(value, ensure_ascii=False, sort_keys=True,
                                 separators=(",", ":")).encode("utf-8")
            return hashlib.sha256(encoded).hexdigest()

        return {"steps": len(keys), "keys": digest(keys), "payloads": digest(payloads),
                "output": digest({"meetings": meetings, "products": products}),
                "bible_version": bible["version"]}
    return asyncio.run(scenario())


@pytest.mark.parametrize("mode", ["solo", "critique", "merge"])
@pytest.mark.parametrize("structure", [None, "v1"])
def test_real_deliberate_and_write_match_85888d5_bytes(mode, structure):
    assert engine_snapshot(mode, structure) == BASELINE[mode]


def test_protected_service_signatures_and_chapter_columns():
    from novel import service
    from novel.store_db import NOVEL_TABLES_DDL
    expected = {"list_books": "(username)", "detail": "(username, novel_id)",
                "bible": "(username, novel_id)", "chapter": "(username, novel_id, number)",
                "owned": "(db, username, novel_id, states=())"}
    assert {name: str(inspect.signature(getattr(service, name))) for name in expected} == expected
    ddl = next(sql for sql in NOVEL_TABLES_DDL if "CREATE TABLE IF NOT EXISTS novel_chapters " in sql)
    assert hashlib.sha256(ddl.encode()).hexdigest() == "45d349c739527b2f972656a498be004a12ea9065ef6f283479f8bb08db3a64d4"


def test_default_structure_and_volume_gate_are_legacy_compatible():
    from novel.service import CreateNovel
    from pydantic import ValidationError
    request = {"seed_idea": "普通主角一路成长", "agents": {
        "editor": "dashscope:qwen3.8-max", "writer": "deepseek:deepseek-flash",
        "archivist": "dashscope:qwen3.8-max"}, "budget_strawberries": 100000}
    assert CreateNovel(**request).structure == "v1"
    assert "volume_gate" not in CreateNovel.model_fields
    with pytest.raises(ValidationError):
        CreateNovel(**request, volume_gate=True)
    assert CreateNovel(**request, structure="v2").structure == "v2"
